e installs regardless.\n    \"python-dotenv>=1.2.2,<1.3.0\",\n    \"pyyaml>=6.0.0,<7.0.0\",\n    \"rich>=13.0.0,<16.0.0\",\n    \"sqlalchemy[asyncio]>=2.0.0,<3.0.0\",\n    \"structlog>=24.0.0,<27.0.0\",\n    \"typer>=0.12.0,<0.28.0\",\n]\n\n[project.urls]\nHomepage = \"https://ouroboros.page/\"\nRepository = \"https://github.com/Q00/ouroboros\"\n\"Bug Tracker\" = \"https://github.com/Q00/ouroboros/issues\"\nSponsor = \"https://github.com/sponsors/Q00\"\n\n[project.optional-dependencies]\n# Exact-pinned (not ranges) on purpose: a future compromised \"latest\" must not\n# be auto-pulled on a fresh PyPI install (pipx / uv tool / pip resolve from\n# this metadata, NOT from uv.lock). Motivated by the 2026-03 litellm\n# 1.82.7/1.82.8 supply-chain incident. Updates land via reviewed Dependabot\n# PRs; uv.lock additionally hash-pins the full transitive graph for repo/CI.\n# Claude's default runtime preserves the Agent SDK and its MCP 1.x graph. The\n# MCP 2 server runs in a separate process/profile; these extras must never be\n# selected in one interpreter.\n# claude-agent-sdk 0.2.144 dropped its own MCP 1.x ceiling; the profile\n# contract (MCP 1.x graph) is preserved by pinning it here explicitly.\nclaude = [\"claude-agent-sdk==0.2.165\", \"anthropic==1.13.0\", \"mcp==1.28.1\"]\nclaude-cli = []\n# Explicit alias for automation and migrations that want to spell out the SDK\n# transport rather than rely on the historical `[claude]` name.\nclaude-sdk = [\"claude-agent-sdk==0.2.165\", \"anthropic==1.13.0\", \"mcp==1.28.1\"]\ncopilot = []\nlitellm = [\"litellm==1.91.0; python_version < '3.14'\"]\ndashboard = []\nmcp = [\"mcp==2.2.0\"]\ntui = [\"textual==8.2.8\", \"textual-serve==1.1.3\"]\n# `[all]` remains the MCP 1.x application bundle. The MCP 2 server profile is\n# explicit and isolated; `[all,mcp]` is intentionally unsupported.\nall = [\"ouroboros-ai[claude,copilot,litellm,tui,dashboard]\"]\n\n[project.scripts]\nooo = \"ouroboros.cli.entrypoint:main\"\nouroboros = \"ouroboros.cli.entrypoint:main\"\nozo = \"ouroboros.cli.commands.zcode:app\"\n\n[build-system]\nrequires = [\"hatchling\", \"hatch-vcs\"]\nbuild-backend = \"hatchling.build\"\n\n[tool.hatch.version]\nsource = \"vcs\"\n\n[tool.hatch.version.raw-options]\nversion_scheme = \"guess-next-dev\"\nlocal_scheme = \"no-local-version\"\n\n[tool.hatch.build.hooks.vcs]\nversion-file = \"src/ouroboros/_version.py\"\n\n[tool.hatch.build]\nexclude = [\n    \"/.smoke-home\",\n    \"**/node_modules\",\n    \"**/target\",\n    \"**/__pycache__\",\n    \"/.mypy_cache\",\n    \"/.pytest_cache\",\n    \"/.ruff_cache\",\n    \"/.venv\",\n    \"/coverage.xml\",\n    \"/.coverage\",\n    # Keep docs (esp. the 7.5MB docs/images/ouroboros.png) out of the sdist —\n    # they are never imported and the wheel already excludes them via\n    # packages=[\"src/ouroboros\"]. Shipping them re-bloated every dev build and\n    # pushed the PyPI project past its 10GB storage cap.\n    \"/docs\",\n]\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/ouroboros\"]\n# Scoped to wheel only: prevent the `packages=` sweep from shipping these\n# assets, so the force-include below is the single source of truth and we\n# avoid duplicate ZIP local headers (PyPI rejects those). The sdist keeps\n# the files at their natural source path so rebuilds from sdist reproduce\n# the same wheel via this same config.\nexclude = [\n    \"src/ouroboros/opencode/plugin/**\",\n    \"src/ouroboros/interview_adapters/packs/**\",\n    \"src/ouroboros/plugin/schemas/**\",\n    \"src/ouroboros/profiles/**\",\n]\n\n[tool.hatch.build.targets.wheel.force-include]\n\"skills\" = \"ouroboros/skills\"\n# Explicit inclusion so `importlib.resources.files(\"ouroboros.opencode.plugin\")`\n# reliably finds ouroboros-bridge.ts / package.json / tsconfig.json in the\n# installed wheel, independent of hatchling's implicit asset handling.\n\"src/ouroboros/opencode/plugin\" = \"ouroboros/opencode/plugin\"\n# Same pattern for the vendored UserLevel plugin 